\begin{ex}%[8H3C3]
\immini[thm]{
Cho hình bình hành  ${A B C D }$ có ${M , N }$ lần lượt là trung điểm của ${A B , C D  }$. Đường ${A N }$ và ${C M }$ cắt ${B D }$ lần lượt tại ${E , F  }$.  Từ ${F }$ kẻ đường thẳng song song với ${A B }$ cắt ${A N }$ tại ${G }$. Trong các khẳng định sau khẳng định nào sai?

\choice
{  $B F =E F =E D $ }
   {  $\Delta {E F G }=\Delta {E D N  }$ }
     { \True  ${ B F G A  }$ là hình thang cân }
    {  ${ A M C N  }$ là hình bình hành }
}{
\begin{tikzpicture}
            \coordinate (A) at (-3, 0);
            \coordinate (D) at (2, 0);
            \coordinate (C) at (3, 2);
            \coordinate (B) at (-2, 2);
           \coordinate (E) at (0.67, 0.67);
            \coordinate (M) at (-2.5, 1);
             \coordinate (N) at (2.5, 1);
              \coordinate (F) at (-0.67, 1.33);
              \coordinate (G) at (-1.17, 0.33);
            % Vẽ tứ giác
            \draw[thick] (M) -- (C);
            \draw[thick] (A) -- (B) -- (C) -- (D) -- (A);
        \draw[thick] (A) -- (N);
        \draw[thick] (B) -- (D);
         \draw[thick] (F) -- (G);
            % Ghi nhãn các điểm
            \node[above left] at (M) {$M $};
            \node[above left] at (B) {$B $};
            \node[above right] at (C) {$C $};
            \node[below right] at (D) {$D $};
            \node[above left] at (A){$A $};
            \node[above right] at (N) {$N $};
            \node[below] at (E) {$E $};
             \node[above] at (F) {$F $};
                \node[above right] at (G) {$G $};
    \end{tikzpicture}
}
\loigiai{
Ta có $\dfrac{1}{2}A B =\dfrac{1}{2}C D  =M B =M A =N C =N D  $\\
và $A M //C N $ nên tứ giác ${ A M C N  }$ là hình bình hành.\\
Tứ giác ${A M F G  }$ có $A M //G F , M F //A G $ nên là hình bình hành suy ra $A M =G F =M B $\\
Lại có $\widehat{F G E } =\widehat{M A G }$ (2 góc đồng vị) và $\widehat{B M F } =\widehat{M A G }$(đồng vị)\\
$\Rightarrow \widehat{F G E }= \widehat{B M F }$\\
$\Delta {B M F }=\Delta{F G E  } $ (g-c-g) $\Rightarrow B F =E F  $\\
Chứng minh tương tự $\Delta {E F G }=\Delta {E D N  }$  (g-c-g) $\Rightarrow E F =E D  $\\
Vậy $B F =E F =E D $\\
Khẳng định sai là ${ B F G A  }$ là hình thang cân vì chưa đủ cơ sở để kết luận.
}\end{ex}

